/* text("foo\nbar\nbaz") */
/** C ref: nhlua.c:812 — @param {CPtr<lua_State>} L @returns {CInt} */
function nhl_text(L) {
    let argc = lua_gettop(L);

    if (argc > 0) {
        let picks = cptr.box(null);
        let tmpwin;

        tmpwin = create_nhwindow()(NHM.NHW_MENU);
        start_menu()(tmpwin, 0n);

        while (lua_gettop(L) > 0) {
            let ostr = dupstr((luaL_checklstring(L, 1, null)));
            let ptr;
            let str = ostr;
            let lstr = cptr.add(cptr.add(str, cptr.strlen(str)), -(1));

            do {
                let nlp = cptr.strchr(str, 10);

                if (nlp && (cptr.diff(nlp, str)) <= 76n) {
                    ptr = nlp;
                } else {
                    ptr = cptr.add(str, 76);
                    if (cptr.cmp(ptr, lstr) > 0)
                        ptr = lstr;
                }
                while ((cptr.cmp(ptr, str) > 0) && !(cptr.ld1s(ptr) == 32 || cptr.ld1s(ptr) == 10))
                    ptr = cptr.add(ptr, -1);
                cptr.st1(ptr, 0);
                add_menu_str(tmpwin, str);
                str = cptr.add(ptr, 1);
            } while (cptr.ld1s(str) && cptr.cmp(str, lstr) <= 0);
            lua_settop(L, -2);
            cptr.free(ostr);
        }

        end_menu()(tmpwin, null);
        void select_menu(tmpwin, NHM.PICK_NONE, picks);
        destroy_nhwindow()(tmpwin);
    }
    return 0;
}

